 for st in s['steps']:
  if st['kind'] in ('GUIDED','CHECK'):st['body']='Use the supplied framework and the conversational function of each letter part. A miss returns to the complete explanation.'
 items={i['id']:i for i in p['items']};ids=['u26-g-letter-writing-0','u26-i-letter-writing-1','u26-i-letter-writing-2']
