 i=items[ids[1]];i.update(prompt='Which English inference is supported by the shown neutral greeting?',options=['a greeting, not a rule about how close the recipient is','every unfamiliar recipient forbids any greeting translated as dear'],answer='a greeting, not a rule about how close the recipient is')
 items[ids[2]]['prompt']='In the supplied letter layout, which English element follows the body?'
