 wrongs=[["every Russian letter must put its main point last overgeneralizes from one framework to all letters and purposes."],["every unfamiliar recipient forbids any greeting translated as dear is not established by the meaning of Здравствуйте!; a greeting does not determine every relationship or register."],["Greeting introduces the reader-facing salutation before the body in this supplied layout.","Sender’s address and date identifies the sender and date before the greeting and body in this supplied layout."]]
 apps=[]
